templates.builtin.raycast_block.loop:
execute unless block ~ ~ ~ #{{datapack_id}}:no_collision run scoreboard players operation .raycast_iter_{{raycastId}} mcs_math = .raycast_end_{{raycastId}} mcs_math
execute if score .raycast_iter_{{raycastId}} mcs_math >= .raycast_end_{{raycastId}} mcs_math run function {{datapack_id}}:user_functions/{{hitFunction}}
{{#if hasLoopFunction}}function {{datapack_id}}:user_functions/{{loopFunction}}{{else}}# No loop function{{/if}}
scoreboard players add .raycast_iter_{{raycastId}} mcs_math 1
execute if score .raycast_iter_{{raycastId}} mcs_math < .raycast_end_{{raycastId}} mcs_math positioned ^ ^ ^0.5 run function {{datapack_id}}:{{loopPath}}

templates.builtin.raycast_block.setup:
data modify storage {{ctxStorage}} current set from storage {{rangeStorage}} {{rangeNbt}}
execute store result score .raycast_end_{{raycastId}} mcs_math run data get storage {{ctxStorage}} current 2
scoreboard players set .raycast_iter_{{raycastId}} mcs_math 0
execute anchored eyes positioned ^ ^ ^.00001 run function {{datapack_id}}:{{loopPath}}
scoreboard players reset .raycast_iter_{{raycastId}} mcs_math
scoreboard players reset .raycast_end_{{raycastId}} mcs_math

templates.builtin.raycast_entity.loop:
execute positioned ~-0.1 ~-0.1 ~-0.1 as @e[tag=!raycast_{{raycastId}}, dx=0] positioned ~-0.7 ~-0.7 ~-0.7 if entity @s[dx=0] run scoreboard players operation .raycast_iter_{{raycastId}} mcs_math = .raycast_end_{{raycastId}} mcs_math
execute if score .raycast_iter_{{raycastId}} mcs_math >= .raycast_end_{{raycastId}} mcs_math positioned ~-0.1 ~-0.1 ~-0.1 as @e[tag=!raycast_{{raycastId}}, dx=0] positioned ~-0.7 ~-0.7 ~-0.7 at @s run function {{datapack_id}}:user_functions/{{hitFunction}}
{{#if hasLoopFunction}}function {{datapack_id}}:user_functions/{{loopFunction}}{{else}}# No loop function{{/if}}
scoreboard players add .raycast_iter_{{raycastId}} mcs_math 1
execute if block ~ ~ ~ #{{datapack_id}}:no_collision if score .raycast_iter_{{raycastId}} mcs_math < .raycast_end_{{raycastId}} mcs_math positioned ^ ^ ^0.5 run function {{datapack_id}}:{{loopPath}}

templates.builtin.raycast_entity.setup:
data modify storage {{ctxStorage}} current set from storage {{rangeStorage}} {{rangeNbt}}
execute store result score .raycast_end_{{raycastId}} mcs_math run data get storage {{ctxStorage}} current 2
scoreboard players set .raycast_iter_{{raycastId}} mcs_math 0
tag @s add raycast_{{raycastId}}
execute anchored eyes positioned ^ ^ ^.00001 run function {{datapack_id}}:{{loopPath}}
tag @s remove raycast_{{raycastId}}
scoreboard players reset .raycast_iter_{{raycastId}} mcs_math
scoreboard players reset .raycast_end_{{raycastId}} mcs_math
